export default {
  currentOperator() {
    const email = (appsmith.user?.email || "").trim().toLowerCase();
    const name = (appsmith.user?.name || "").trim();
    if (email) return email;
    if (name) return name;
    return "system";
  },

	async init() {
		await storeValue("ster_in_error", "");
		await storeValue("ster_in_default_size", "");
		await storeValue("ster_in_submitting", false);
		await storeValue("ster_in_last_success_signature", "");
		await storeValue("ster_in_last_created_run_id", "");
		await Promise.allSettled([qItems.run(), qRecipes.run()]);
	},

	validate({ show = true } = {}) {
		const errs = [];

		if (!selProcessType.selectedOptionValue) {
			errs.push("Select a process type.");
		}

		if (!selPlannedItem.selectedOptionValue) {
			errs.push("Select a planned item.");
		}

		if (!selPlannedRecipe.selectedOptionValue) {
			errs.push("Select a planned recipe.");
		}

		const unit = Number(inpPlannedUnitSize.text);
		const cnt = Number(inpPlannedCount.text);

		if (!Number.isFinite(unit) || unit <= 0) {
			errs.push("Planned unit size must be > 0.");
		}

		if (!Number.isFinite(cnt) || cnt <= 0) {
			errs.push("Planned count must be > 0.");
		}

		if (show) {
			errs.forEach(msg => showAlert(msg, "error"));
		}

		return errs;
	},

  sql: {
    str(v) {
      if (v === undefined || v === null) return "NULL";
      return "'" + String(v).replace(/'/g, "''") + "'";
    },
    ts(d) {
      if (!d) return "NULL";
      // format without the ISO 'T'
      const s = moment(d).format("YYYY-MM-DD HH:mm:ss");
      return "'" + s + "'";
    },
    num(v) {
      const n = Number(v);
      return Number.isFinite(n) ? String(n) : "NULL";
    },
  },

	formSignature() {
		return JSON.stringify({
			planned_item_id: selPlannedItem.selectedOptionValue || "",
			planned_recipe_id: selPlannedRecipe.selectedOptionValue || "",
			process_type: selProcessType.selectedOptionValue || "",
			planned_count: String(inpPlannedCount.text || "").trim(),
			planned_unit_size: String(inpPlannedUnitSize.text || "").trim(),
			start_time: dpStartTime.formattedDate || ""
		});
	},

	isSubmitting() {
		return appsmith.store.ster_in_submitting === true;
	},

	isDuplicateOfLastSuccess() {
		const current = this.formSignature();
		return !!current && current === appsmith.store.ster_in_last_success_signature;
	},

	async markFormChanged() {
		await storeValue("ster_in_last_success_signature", "");
		await storeValue("ster_in_error", "");
	},

	async resetCreateRunForm() {
		await selPlannedItem.setSelectedOption("");
		await selPlannedRecipe.setSelectedOption("");
		await selProcessType.setSelectedOption("sterilize");
		await inpPlannedCount.setValue("");
		await inpPlannedUnitSize.setValue("");
		await dpStartTime.setValue(new Date());
		await storeValue("ster_in_default_size", "");
	},

	async createRun() {
		if (this.isSubmitting()) {
			return;
		}

		await storeValue("ster_in_submitting", true);
		await storeValue("ster_in_error", "");

		try {
			const errs = this.validate({ show: true });
			if (errs.length) {
				await storeValue("ster_in_error", errs.join(" "));
				return;
			}

			const signature = this.formSignature();

			if (signature === appsmith.store.ster_in_last_success_signature) {
				showAlert(
					"This run was already created. Change the inputs before creating another run.",
					"warning"
				);
				return;
			}

			const createdRun = await qCreateRun.run();
			const runId = createdRun?.[0]?.steri_run_id || "(unknown run)";
			const msg = "Successfully created sterilizer run " + runId;

			await storeValue("ster_in_last_success_signature", signature);
			await storeValue("ster_in_last_created_run_id", runId);
			await storeValue("ster_in_error", msg);

			showAlert(msg, "success");

			await this.resetCreateRunForm();

			await Promise.allSettled([
				qItems.run(),
				qRecipes.run()
			]);
		} catch (e) {
			const msg = e && e.message ? e.message : String(e);
			showAlert("Error creating run: " + msg, "error");
			await storeValue("ster_in_error", msg);
		} finally {
			await storeValue("ster_in_submitting", false);
		}
	},

	async setSelectedItemSize() {
    const selectedValue = selPlannedItem.selectedOptionValue; // Get the selected 'value' (e.g., "1")

    // Find the full object in the original data array
    const selectedItem = qItems.data.find(item => item.nocopk === selectedValue);

		if (selectedItem) {
      // Use this data for further actions, such as running another query or updating another widget
      storeValue('ster_in_default_size', selectedItem.default_unit_size_lb || selectedItem.default_unit_size_ml || selectedItem.default_unit_size_g || selectedItem.default_unit_size_oz || '');
    } 
  },

  async refresh() {
    await this.init();
  },
};

