		inpHarvestFlushNo.setValue(String(nextFlush));

		await LotsHarvest.onHarvestCountsChanged();

		await showModal(modalHarvestLot.name);
	},

	harvestFreshTrayCount() {
		const count = Number(inpHarvestFreshTrayCount.text || 0);
		return Number.isFinite(count) && count > 0 ? count : 0;
	},

	harvestFrozenTrayCount() {
		const count = Number(inpHarvestFrozenTrayCount.text || 0);
		return Number.isFinite(count) && count > 0 ? count : 0;
	},

