export default {
  currentOperator() {
    const email = (appsmith.user?.email || "").trim().toLowerCase();
    const name = (appsmith.user?.name || "").trim();
    if (email) return email;
    if (name) return name;
    return "system";
  },

  sql: {
    str(v) {
      if (v === undefined || v === null || v === "") return "NULL";
      return "'" + String(v).replace(/'/g, "''") + "'";
    },
    num(v) {
      const n = Number(v);
      return Number.isFinite(n) ? String(n) : "NULL";
    },
    arrBigint(arr) {
      if (!arr || arr.length === 0) return "ARRAY[]::bigint[]";
      const vals = arr.map(x => {
        const n = Number(x);
        return Number.isFinite(n) ? String(n) : "NULL";
      }).filter(x => x !== "NULL");
      if (vals.length === 0) return "ARRAY[]::bigint[]";
      return "ARRAY[" + vals.join(", ") + "]::bigint[]";
    }
  },

  selectedProductIds() {
    return (tblProducts.selectedRows || [])
      .map(r => Number(r.nocopk))
      .filter(Number.isFinite);
  },

  selectedTrayProducts() {
    return (tblProducts.selectedRows || []).filter(r =>
      ["fresh_tray", "freezer_tray"].includes(String(r.item_category_mat || ""))
    );
  },

  selectedFreezerTrayProducts() {
    return (tblProducts.selectedRows || []).filter(r =>
      String(r.item_category_mat || "") === "freezer_tray"
    );
  },

  selectedProductsSummary() {
    const rows = tblProducts.selectedRows || [];
    if (!rows.length) return "No products selected.";

    return rows.map(r =>
      `${r.product_id || r.nocopk} — ${r.name || r.item_category_mat || "Product"} — ${r.storage_location || "No location"}`
    ).join("\n");
  },

	isActiveProduct(row) {
		const trayStates = String(row?.tray_state || "")
			.toLowerCase()
			.split(/[,;|]+/)
			.map(s => s.trim())
			.filter(Boolean);

		const location = String(row?.storage_location || "")
			.toLowerCase()
			.replace(/[^a-z0-9]/g, "");

		const inactiveStates = [
			"empty_tray",
			"empty tray",
			"compost",
			"composted",
			"spoiled",
			"retired",
			"expired",
			"consumed",
			"shipped"
		];

		const inactiveLocations = [
			"compost",
			"expired",
			"shipped"
		];

		return !trayStates.some(s => inactiveStates.includes(s))
			&& !inactiveLocations.includes(location);
	},

	isActiveTrayProduct(row) {
		return ProductsPage.isActiveProduct(row);
	},

	async refresh() {
		await Promise.allSettled([
			qProductLocationOptions.run(),
			qProductStrainOptions.run(),
			qFreezeDriedPackageItems.run()
		]);
		await qProducts.run();
	},

  async showFreshTrays() {
    await selProductsCategory.setSelectedOption("fresh_tray");
    await ProductsPage.refresh();
  },

  async showFreezerTrays() {
    await selProductsCategory.setSelectedOption("freezer_tray");
    await ProductsPage.refresh();
  },

  productReadyLocationOptions() {
    const invalidNameParts = [
      "dark room",
      "fruiting",
      "freeze",
      "freezer",
      "fridge",
      "refrigerat",
      "cold shock",
      "lab",
      "shipped",
      "consumed",
      "compost",
      "expired",
      "retired"
    ];

    const preferredNameParts = [
      "products storage",
      "product storage",
      "fulfillment",
      "shipping",
      "retail",
      "market",
      "customer"
    ];

    return (qProductLocationOptions.data || [])
      .filter(l => {
        const name = String(l.name || "").trim();
        const lower = name.toLowerCase();

        if (!name) return false;
        if (l.active === false) return false;
        if (invalidNameParts.some(part => lower.includes(part))) return false;

        return preferredNameParts.some(part => lower.includes(part));
      })
      .map(l => ({
        label: l.name,
        value: l.nocopk
      }));
  },

  defaultProductReadyLocationId() {
    const opts = this.productReadyLocationOptions();

    const productsStorage = opts.find(o =>
      String(o.label || "").trim().toLowerCase() === "products storage"
    );

    return (productsStorage || opts[0])?.value || "";
  },

	isMoveFreezeDryerSubmitting() {
		return appsmith.store.products_move_freeze_dryer_submitting === true;
	},

	isRetireTraySubmitting() {
		return appsmith.store.products_retire_tray_submitting === true;
	},

	isPackageFreezeDriedSubmitting() {
		return appsmith.store.products_package_fd_submitting === true;
	},	

  freezeDryerLocationOptions() {
    return (qProductLocationOptions.data || [])
      .filter(l => {
        const name = String(l.name || "").toLowerCase();
        return l.active !== false && name.includes("freeze dryer");
      })
      .map(l => ({
        label: l.name,
        value: l.nocopk
      }));
  },

  defaultFreezeDryerLocationId() {
    const opts = this.freezeDryerLocationOptions();
    return opts[0]?.value || "";
  },

  canMoveFreezeDryer() {
    const rows = tblProducts.selectedRows || [];
    return rows.length > 0 && rows.every(r =>
      String(r.item_category_mat || "") === "freezer_tray" &&
      this.isActiveTrayProduct(r)
    );
  },

  canRetireTray() {
    const rows = tblProducts.selectedRows || [];
    return rows.length > 0 && rows.every(r =>
      ["fresh_tray", "freezer_tray"].includes(String(r.item_category_mat || "")) &&
      this.isActiveTrayProduct(r)
    );
  },

	canPackageFreezeDried() {
		const rows = tblProducts.selectedRows || [];

		return rows.length > 0
			&& rows.every(r => String(r.item_category_mat || "") === "freezer_tray")
			&& rows.every(r => ProductsPage.isActiveTrayProduct(r));
	},

	canSubmitMoveFreezeDryer() {
		if (ProductsPage.isMoveFreezeDryerSubmitting()) {
			return false;
		}

		const selectedLocationId = selFreezeDryerLocation.selectedOptionValue;
		const validLocationIds = ProductsPage.freezeDryerLocationOptions()
			.map(o => String(o.value));

		return ProductsPage.canMoveFreezeDryer()
			&& !!selectedLocationId
			&& validLocationIds.includes(String(selectedLocationId));
	},

	canSubmitRetireTray() {
		if (ProductsPage.isRetireTraySubmitting()) {
			return false;
		}

		return ProductsPage.canRetireTray()
			&& !!selRetireTrayReason.selectedOptionValue;
	},

	freezeDriedPackageItemOptions() {
		return (qFreezeDriedPackageItems.data || [])
			.filter(i => i && i.nocopk)
			.map(i => ({
				label: i.label || `${i.name || i.item_id || i.nocopk}`,
				value: i.nocopk,
				default_unit_size: i.default_unit_size
			}));
	},

	defaultFreezeDriedPackageItemId() {
		const opts = this.freezeDriedPackageItemOptions();
		return opts[0]?.value || "";
	},

	selectedFreezeDriedPackageItem() {
		const selected = selPkgFDPackageItem.selectedOptionValue;
		return (qFreezeDriedPackageItems.data || [])
			.find(i => String(i.nocopk) === String(selected)) || null;
	},

	canSubmitPackageFreezeDried() {
		if (ProductsPage.isPackageFreezeDriedSubmitting()) {
			return false;
		}

		const count = Number(inpPkgFDCount.text);
		const sizeG = Number(inpPkgFDSizeG.text);
		const rows = tblProducts.selectedRows || [];

		const selectedPackageItemId = selPkgFDPackageItem.selectedOptionValue;
		const validPackageItemIds = ProductsPage.freezeDriedPackageItemOptions()
			.map(o => String(o.value));

		const selectedLocationId = selPkgFDLocation.selectedOptionValue;
		const validLocationIds = ProductsPage.productReadyLocationOptions()
			.map(o => String(o.value));

		const selectedWeightG = rows.reduce(
			(sum, r) => sum + Number(r.net_weight_g || 0),
			0
		);

		const requiredWeightG = count * sizeG;

		return ProductsPage.canPackageFreezeDried()
			&& Number.isFinite(count)
			&& count > 0
			&& Number.isFinite(sizeG)
			&& sizeG > 0
			&& selectedWeightG >= requiredWeightG
			&& !!selectedPackageItemId
			&& validPackageItemIds.includes(String(selectedPackageItemId))
			&& !!selectedLocationId
			&& validLocationIds.includes(String(selectedLocationId));
	},

	async openMoveFreezeDryerModal() {
		if (!ProductsPage.canMoveFreezeDryer()) {
			showAlert("Select one or more active freezer tray products.", "warning");
			return;
		}

		await storeValue("products_move_freeze_dryer_submitting", false);

		inpMoveFreezeDryerNotes.setValue("");

		const defaultLocationId = ProductsPage.defaultFreezeDryerLocationId();

		if (defaultLocationId) {
			await selFreezeDryerLocation.setSelectedOption(defaultLocationId);
		} else {
			await selFreezeDryerLocation.setSelectedOption("");
			showAlert("No active Freeze Dryer location was found.", "warning");
		}

		await showModal(modalMoveFreezeDryer.name);
	},

	async onFreezeDriedPackageItemChanged() {
		const sizeG = this.freezeDriedPackageItemSizeG();

		if (sizeG) {
			await inpPkgFDSizeG.setValue(String(sizeG));
		} else {
			await inpPkgFDSizeG.setValue("");
			showAlert(
				"Selected package item does not have default_unit_size_g or default_unit_size_oz.",
				"warning"
			);
		}
	},

	freezeDriedPackageItemSizeG(item = this.selectedFreezeDriedPackageItem()) {
		if (!item) return "";

		const sizeG = Number(item.default_unit_size_g);
		if (Number.isFinite(sizeG) && sizeG > 0) {
			return sizeG;
		}

		const sizeOz = Number(item.default_unit_size_oz);
		if (Number.isFinite(sizeOz) && sizeOz > 0) {
			return +(sizeOz * 28.349523125).toFixed(2);
		}

		return "";
	},

	async openPackageFreezeDriedModal() {
		if (!this.canPackageFreezeDried()) {
			showAlert("Select one or more active freezer tray products.", "warning");
			return;
		}

		await storeValue("products_package_fd_submitting", false);

		const rows = tblProducts.selectedRows || [];

		if (!rows.length || !rows.every(r => String(r.item_category_mat || "") === "freezer_tray")) {
			showAlert("Select one or more freezer tray products to package.", "warning");
			return;
		}

		if (!rows.every(r => this.isActiveTrayProduct(r))) {
			showAlert("Only active freezer tray products can be packaged.", "warning");
			return;
		}

		await Promise.allSettled([
			qProductLocationOptions.run(),
			qFreezeDriedPackageItems.run()
		]);

		inpPkgFDCount.setValue(inpPkgFDCount.text || "1");
		inpPkgFDNotes.setValue("");

		const defaultPackageItemId = this.defaultFreezeDriedPackageItemId();
		if (defaultPackageItemId) {
			await selPkgFDPackageItem.setSelectedOption(defaultPackageItemId);
			await this.onFreezeDriedPackageItemChanged();
		} else {
			await selPkgFDPackageItem.setSelectedOption("");
			await inpPkgFDSizeG.setValue("");
			showAlert("No active freeze-dried package item was found. Add an item with category freezedriedmushrooms.", "warning");
		}

		const defaultLocationId = this.defaultProductReadyLocationId();
		if (defaultLocationId) {
			await selPkgFDLocation.setSelectedOption(defaultLocationId);
		} else {
			await selPkgFDLocation.setSelectedOption("");
			showAlert("No product-ready storage location was found. Add or activate Products Storage before packaging.", "warning");
		}

		await showModal(modalPackageFreezeDried.name);
	},

	async openRetireTrayModal() {
		if (!ProductsPage.canRetireTray()) {
			showAlert("Select one or more active tray products.", "warning");
			return;
		}

		await storeValue("products_retire_tray_submitting", false);

		await selRetireTrayReason.setSelectedOption("");
		await inpRetireTrayNotes.setValue("");

		await showModal(modalRetireTray.name);
	},

	async moveToFreezeDryer() {
		if (ProductsPage.isMoveFreezeDryerSubmitting()) {
			return;
		}

		if (!ProductsPage.canSubmitMoveFreezeDryer()) {
			showAlert("Select active freezer tray products and a Freeze Dryer location.", "warning");
			return;
		}

		await storeValue("products_move_freeze_dryer_submitting", true);

		try {
			const res = await qMoveProductsToFreezeDryer.run();

			showAlert("Moved freezer tray product(s) to Freeze Dryer.", "success");

			closeModal(modalMoveFreezeDryer.name);

			await ProductsPage.refresh();

			return res;
		} catch (e) {
			showAlert(e?.message || String(e), "error");
			return null;
		} finally {
			await storeValue("products_move_freeze_dryer_submitting", false);
		}
	},

	async retireTrayProducts() {
		if (ProductsPage.isRetireTraySubmitting()) {
			return;
		}

		if (!ProductsPage.canSubmitRetireTray()) {
			showAlert("Select active tray products and a reason.", "warning");
			return;
		}

		await storeValue("products_retire_tray_submitting", true);

		try {
			const res = await qRetireTrayProducts.run();

			showAlert("Tray product(s) updated.", "success");

			closeModal(modalRetireTray.name);

			await ProductsPage.refresh();

			return res;
		} catch (e) {
			showAlert(e?.message || String(e), "error");
			return null;
		} finally {
			await storeValue("products_retire_tray_submitting", false);
		}
	},

	async packageFreezeDried() {
		if (ProductsPage.isPackageFreezeDriedSubmitting()) {
			return;
		}

		if (!ProductsPage.canSubmitPackageFreezeDried()) {
			showAlert("Select enough active freezer tray product weight and complete the package form.", "warning");
			return;
		}

		await storeValue("products_package_fd_submitting", true);

		try {
			const res = await qPackageFreezeDried.run();

			showAlert("Packaged freeze dried product(s) created.", "success");

			closeModal(modalPackageFreezeDried.name);

			await ProductsPage.refresh();

			return res;
		} catch (e) {
			showAlert(e?.message || String(e), "error");
			return null;
		} finally {
			await storeValue("products_package_fd_submitting", false);
		}
	},
};

