export default {
  currentOperator() {
    const email = (appsmith.user?.email || "").trim().toLowerCase();
    const name = (appsmith.user?.name || "").trim();
    if (email) return email;
    if (name) return name;
    return "system";
  },

  async init() {
    await storeValue('personnel_reviews_error', '');
    await Promise.allSettled([
      qPersonnelSubjects.run(),
      qPersonnelRecentEntries.run()
    ]);
  },

	sql: {
		str(v) {
			if (v === undefined || v === null || String(v).trim() === "") return "NULL";
			return "'" + String(v).trim().replace(/'/g, "''") + "'";
		},

		ts(v) {
			if (!v) return null;
			return moment(v).format("YYYY-MM-DD HH:mm:ss");
		},

		date(v) {
			if (!v) return null;
			return moment(v).format("YYYY-MM-DD");
		},

		textArray(vals) {
			if (!vals || !Array.isArray(vals) || !vals.length) return null;
			return vals.map(v => String(v));
		}
	},

  validate() {
    const errs = [];

    if (!selPRSubject.selectedOptionValue) {
      errs.push("Select an employee.");
    }
    if (!inpPREnteredBy.text || !inpPREnteredBy.text.trim()) {
      errs.push("Entered By is required.");
    }
    if (!selPREntrySource.selectedOptionValue) {
      errs.push("Select an entry source.");
    }
    if (!selPRNoteType.selectedOptionValue) {
      errs.push("Select a note type.");
    }
    if (!selPRCategory.selectedOptionValue) {
      errs.push("Select a category.");
    }
    if (!selPRVisibility.selectedOptionValue) {
      errs.push("Select a visibility.");
    }
    if (!inpPRSummary.text || !inpPRSummary.text.trim()) {
      errs.push("Summary is required.");
    }
    if (chkPRFollowUpNeeded.isChecked && !dpPRFollowUpBy.selectedDate) {
      errs.push("Select a follow-up date or uncheck Follow Up Needed.");
    }

    return errs;
  },

  async submitEntry() {
    await storeValue('personnel_reviews_error', '');
    const errs = this.validate();

    if (errs.length) {
      const msg = errs.join(" ");
      await storeValue('personnel_reviews_error', msg);
      showAlert(msg, "error");
      return;
    }

    try {
      const result = await qInsertPersonnelReviewEntry.run();
      const insertedId = result?.[0]?.inserted_id;

      showAlert(
        "Personnel review entry saved" + (insertedId ? " (#" + insertedId + ")" : "") + ".",
        "success"
      );

      await this.resetForm();
      await qPersonnelRecentEntries.run();
    } catch (e) {
      const msg = e && e.message ? e.message : String(e);
      await storeValue('personnel_reviews_error', msg);
      showAlert("Error saving personnel review entry: " + msg, "error");
    }
  },

  async resetForm() {
    inpPRSummary.setValue("");
    inpPRDetails.setValue("");
    chkPRFollowUpNeeded.setValue(false);
    dpPRFollowUpBy.setValue("");
    msPRTags.setSelectedOptions([]);
    await storeValue('personnel_reviews_error', '');
  },

  quickNow() {
    return moment().format("YYYY-MM-DD HH:mm:ss");
  },

  selectedSubjectLabel() {
    const selected = qPersonnelSubjects.data?.find(
      r => String(r.nocopk) === String(selPRSubject.selectedOptionValue)
    );
    if (!selected) return "";
    return [
      selected.full_name || "",
      selected.role_title ? "(" + selected.role_title + ")" : "",
      selected.entry_count != null ? "- entries: " + selected.entry_count : ""
    ].filter(Boolean).join(" ");
  }
};

