  spawnSourceLotIds() {
    return LotsSpawnToBulk.spawnSourceRows()
      .map(r => Number(r.nocopk))
      .filter(Number.isFinite);
  },

  spawnToBulkSourceLotIds() {
    return LotsSpawnToBulk.spawnSourceLotIds();
  },

  substrateLotIds() {
    return LotsSpawnToBulk.substrateSourceRows()
      .map(r => Number(r.nocopk))
      .filter(Number.isFinite);
  },

  spawnToBulkTargetLotIds() {
    return LotsSpawnToBulk.substrateLotIds();
  },

  formatSelectedLots() {
    const rows = LotsSpawnToBulk.selectedLotRows();

    if (!rows.length) return "(No lots selected)";

    return rows.map(r => {
      const lotId = r.lot_id ?? r.nocopk;
      const inoc = r.inoculated_at
        ? moment(r.inoculated_at).format("YYYY-MM-DD")
        : "";
      const item = r.item_name_mat || r.item_name || "";
      const strain = r.strain_species_strain_mat || r.strain_species_strain || "";
      const status = r.status || "";

      return `${lotId} | inoc:${inoc} | ${item} | ${strain} | ${status}`.trim();
    }).join("\n");
  },

  spawnToBulkNotesText() {
    return String(inpSpawnToBulkNotes.text || "").trim();
  },

  spawnToBulkBlockSizesText() {
    return String(inpSpawnToBulkLotsSize.text || "").trim();
  },

  spawnToBulkOutputPlan() {
    const text = LotsSpawnToBulk.spawnToBulkBlockSizesText();

    if (!text) return [];

    return text
      .split(",")
      .map(s => s.trim())
      .filter(Boolean)
      .map(token => {
        if (token.includes(":")) {
          const [item_code, ratio] = token.split(":").map(x => x.trim());
          return {
            item_code,
            ratio: Number(ratio)
          };
        }

        return {
          ratio: Number(token)
        };
      })
      .filter(x => Number.isFinite(x.ratio) && x.ratio > 0);
  },

  spawnToBulkOutputPlanJson() {
    return JSON.stringify(LotsSpawnToBulk.spawnToBulkOutputPlan());
  },

  spawnToBulkOutputCount() {
    const explicitCount = Number(inpSpawnToBulkNumLots.text);
    if (Number.isFinite(explicitCount) && explicitCount > 0) {
      return explicitCount;
    }

    const plan = LotsSpawnToBulk.spawnToBulkOutputPlan();
    if (plan.length > 0) return plan.length;

    return LotsSpawnToBulk.substrateLotIds().length;
  },

  selectedSourceSpeciesKeys() {
    return [
      ...new Set(
        LotsSpawnToBulk.spawnSourceRows()
          .map(r => String(
            r.strain_species_strain_mat ||
            r.strain_species_strain ||
            ""
          ).trim())
          .filter(Boolean)
      )
    ];
  },

  spawnToBulkLocationOptions() {
    return (qSpawnToBulkLocations.data || [])
      .filter(l => l && l.nocopk != null)
      .map(l => ({
        label: l.name,
        value: l.nocopk
      }));
  },

  defaultSpawnToBulkLocationId() {
    const opts = LotsSpawnToBulk.spawnToBulkLocationOptions();

    const darkRoom = opts.find(o =>
      String(o.label || "").trim().toLowerCase() === "dark room"
    );

    const colonizing = opts.find(o =>
      String(o.label || "").toLowerCase().includes("colon")
    );

    const incubation = opts.find(o =>
      String(o.label || "").toLowerCase().includes("incubat")
    );

    return (darkRoom || colonizing || incubation || opts[0])?.value || "";
  },

  selectedSpawnToBulkLocationId() {
    const selected = setSpawnToBulkLocation.selectedOptionValue;
    return selected || LotsSpawnToBulk.defaultSpawnToBulkLocationId();
  },

  hasValidSpawnToBulkLocation() {
    const selectedLocationId = LotsSpawnToBulk.selectedSpawnToBulkLocationId();
    const validLocationIds = LotsSpawnToBulk.spawnToBulkLocationOptions()
      .map(o => String(o.value));

    return !!selectedLocationId
      && validLocationIds.includes(String(selectedLocationId));
  },

  canSubmitSpawnToBulk() {
    const targets = LotsSpawnToBulk.substrateSourceRows();
    const sources = LotsSpawnToBulk.spawnSourceRows();
    const targetIds = LotsSpawnToBulk.substrateLotIds();
    const sourceIds = LotsSpawnToBulk.spawnSourceLotIds();
    const outputCount = LotsSpawnToBulk.spawnToBulkOutputCount();
    const sourceSpecies = LotsSpawnToBulk.selectedSourceSpeciesKeys();

    if (!LotsSpawnToBulk.canOpenModal()) return false;
    if (targetIds.length < 1) return false;
    if (sourceIds.length < 1) return false;

    if (!targets.every(r => LotsSpawnToBulk.targetIsEligible(r))) return false;
    if (!sources.every(r => LotsSpawnToBulk.sourceIsEligible(r))) return false;

    /*
      Spawn to Bulk should use grain sources from one species/strain grouping.
      Substrate lots may not yet have strain fields, so this intentionally
      validates the source grain selection rather than requiring target strain.
    */
    if (sourceSpecies.length !== 1) return false;

    if (!Number.isFinite(outputCount) || outputCount <= 0) return false;
    if (!LotsSpawnToBulk.hasValidSpawnToBulkLocation()) return false;

    return true;
  },

  async resetModal() {
    resetWidget("tblSpawnSourceLots", false);
    resetWidget("inpSpawnToBulkNotes", true);
    resetWidget("inpSpawnToBulkLotsSize", true);
    resetWidget("inpSpawnToBulkNumLots", true);
  },

  async spawnSelected() {
    if (!LotsSpawnToBulk.canSubmitSpawnToBulk()) {
      showAlert("Select active unspawned substrate targets, one or more colonized grain source lots of the same species, and a valid Dark Room/colonizing destination.", "warning");
      return null;
    }

    try {
      const res = await qSpawnToBulkLots.run();
      const created = res?.[0]?.created_count ?? 0;

      showAlert(`Spawn to Bulk complete. Created ${created} fruiting block lot(s).`, "success");

      await Promise.allSettled([
        qLots.run(),
        qSpecies.run(),
        qSpawnSourceLotsSearch.run()
      ]);
      await LotsSpawnToBulk.resetModal();

      return res;
    } catch (e) {
      const message = e?.message || String(e);

      showAlert(message, "error");
      await storeValue("lots_error", message);

      return null;
    }
  },

  async submitSpawnToBulk() {
    return LotsSpawnToBulk.spawnSelected();
  }
};

