				requireNotInoculated: true,
				message: "Select one or more active grain, LC flask, plate, or cordyceps substrate lots that have not already been inoculated or assigned a strain."
			},
			draw_syringes: {
				requireSingle: true,
				allowedCategories: ["lc_flask"],
				message: "Select exactly one active LC flask lot to draw syringes."
			},
			harvest: {
				requireSingle: true,
				allowedCategories: ["fruiting_block", "cordyceps_substrate"],
				message: "Select exactly one active fruiting block or cordyceps substrate lot to harvest."
			}
		};

		const rules = {
			...(action ? (rulesByAction[action] || {}) : {}),
			...options
		};

		if (rules.requireSingle && rows.length !== 1) {
