			showAlert(result.message || fallbackMessage, "warning");
			return false;
		}

		return true;
	},

	async refresh() {
		await qLots.run();
		await qSyringeItems.run();
	},

	syringeItemOptions() {
		return (qSyringeItems.data || [])
			.filter(i => i && i.nocopk)
			.map(i => ({
				label: i.label || `${i.name || i.item_id || i.nocopk}`,
				value: i.nocopk,
				default_unit_size_ml: i.default_unit_size_ml
			}));
	},

	defaultSyringeItemId() {
		const opts = LotsDrawSyringes.syringeItemOptions();
		return opts[0]?.value || "";
	},

	selectedSyringeItem() {
		const selected = selSyringeItem.selectedOptionValue;
		return (qSyringeItems.data || [])
			.find(i => String(i.nocopk) === String(selected)) || null;
	},

	selectedFlaskLot() {
		return LotsDrawSyringes.selectedLotRows()[0] || null;
	},

	selectedFlaskRemainingMl() {
		const row = LotsDrawSyringes.selectedFlaskLot();
