async function () {
  if (SterilizerIn.isSubmitting()) {
    return;
  }
  await storeValue("ster_in_submitting", true);
  await storeValue("ster_in_error", "");
  try {
    const errs = SterilizerIn.validate({
      show: true
    });
    if (errs.length) {
      await storeValue("ster_in_error", errs.join(" "));
      return;
    }
    const signature = SterilizerIn.formSignature();
    if (signature === appsmith.store.ster_in_last_success_signature) {
      showAlert("This run was already created. Change the inputs before creating another run.", "warning");
      return;
    }
    const createdRun = await qCreateRun.run();
    const runId = createdRun?.[0]?.steri_run_id || "(unknown run)";
    const msg = "Successfully created sterilizer run " + runId;
    await storeValue("ster_in_last_success_signature", signature);
    await storeValue("ster_in_last_created_run_id", runId);
    await storeValue("ster_in_error", msg);
    showAlert(msg, "success");
    await SterilizerIn.resetCreateRunForm();
    await Promise.allSettled([qItems.run(), qRecipes.run()]);
  } catch (e) {
    const msg = e && e.message ? e.message : String(e);
    showAlert("Error creating run: " + msg, "error");
    await storeValue("ster_in_error", msg);
  } finally {
    await storeValue("ster_in_submitting", false);
  }
}

