  }
  if (lower.includes("fridge") || lower.includes("refrigerat")) {
    return "fridge";
  }
  if (lower.includes("fruiting")) {
    return "fruiting";
  }
  if (lower.includes("dark room")) {
    return "dark_room";
  }
  if (lower.includes("products storage") || lower.includes("product storage") || lower.includes("fulfillment") || lower.includes("shipping") || lower.includes("retail") || lower.includes("market")) {
    return "product_storage";
  }
  if (lower.includes("new") || lower.includes("receiving") || lower.includes("intake") || lower.includes("staging")) {
    return "new_lot";
  }
  if (lower.includes("lab")) {
    return "lab";
  }
  return "other";
}

