actionConfiguration.body:
async function () {
  if (LotsPage.isPackageSubmitting()) {
    return;
  }
  if (!LotsPage.canSubmitPackage()) {
    showAlert("Select one packageable lot and a product-ready storage location.", "warning");
    return;
  }
  const count = Number(inpPackageCount.text);
  const sizeG = Number(inpPackageSizeG.text);
  const selectedWeightG = Number(LotsPage.selectedPackageWeightG());
  if (!Number.isFinite(selectedWeightG) || selectedWeightG <= 0) {
    showAlert("Selected lot does not have a packageable weight. The lot has no gram weight and its item does not have default_unit_size_g, default_unit_size_oz, or default_unit_size_lb.", "warning");
    return;
  }
  if (count !== 1) {
    showAlert("Package workflow currently expects exactly one package.", "warning");
    return;
  }
  if (!Number.isFinite(sizeG) || sizeG <= 0) {
    showAlert("Package weight must be greater than 0.", "warning");
    return;
  }
  if (Math.abs(selectedWeightG - sizeG) >= 0.001) {
    showAlert(`Package weight must match selected lot weight. Expected ${selectedWeightG} g.`, "warning");
    return;
  }
  await storeValue("lots_package_submitting", true);
  try {
    const lotspackaged = await qPackageLots.run();
    showAlert("Packaged " + lotspackaged[0].packaged_count + " lot(s).", "success");
    txtPackageContent.setText("");
    inpPackageNotes.setValue("");
    closeModal(modalPackageLots.name);
    await qLots.run();
    return lotspackaged;
  } catch (e) {
    const message = e && e.message ? e.message : String(e);
    showAlert("Error packaging lots: " + message, "error");
    await storeValue("lots_error", message);
    return null;
  } finally {
    await storeValue("lots_package_submitting", false);
  }
}

