async function () {
  if (!LotsSpawnToBulk.canSubmitSpawnToBulk()) {
    showAlert("Select active unspawned substrate targets, one or more colonized grain source lots of the same species, and a valid Dark Room/colonizing destination.", "warning");
    return null;
  }
  try {
    const res = await qSpawnToBulkLots.run();
    const created = res?.[0]?.created_count ?? 0;
    showAlert(`Spawn to Bulk complete. Created ${created} fruiting block lot(s).`, "success");
    closeModal(modalSpawnToBulk.name);
    await LotsPage.refresh();
    await LotsSpawnToBulk.resetModal();
    return res;
  } catch (e) {
    const message = e?.message || String(e);
    showAlert(message, "error");
    await storeValue("lots_error", message);
    return null;
  }
}

