function (row) {
  const category = LotsSpawnToBulk.normalizeCategory(row?.item_category_mat || row?.item_category);
  const status = LotsSpawnToBulk.normalizeStatus(row?.status);
  const strain = String(row?.strain_species_strain_mat || row?.strain_species_strain || "").trim();
  if (category !== "grain") return false;
  if (LotsSpawnToBulk.lotIsTerminal(row)) return false;
  if (!strain) return false;
  return ["colonizing", "colonized", "fullycolonized", "fridge", "colonizedfridge"].some(s => status.includes(s));
}

