actionConfiguration.body:
async function () {
  if (ProductsPage.isPackageFreezeDriedSubmitting()) {
    return;
  }
  if (!ProductsPage.canSubmitPackageFreezeDried()) {
    showAlert("Select enough active freezer tray product weight and complete the package form.", "warning");
    return;
  }
  await storeValue("products_package_fd_submitting", true);
  try {
    const res = await qPackageFreezeDried.run();
    showAlert("Packaged freeze dried product(s) created.", "success");
    closeModal(modalPackageFreezeDried.name);
    await ProductsPage.refresh();
    return res;
  } catch (e) {
    showAlert(e?.message || String(e), "error");
    return null;
  } finally {
    await storeValue("products_package_fd_submitting", false);
  }
}

