function () {
  if (ProductsPage.isPackageFreezeDriedSubmitting()) {
    return false;
  }
  const count = Number(inpPkgFDCount.text);
  const sizeG = Number(inpPkgFDSizeG.text);
  const rows = tblProducts.selectedRows || [];
  const selectedPackageItemId = selPkgFDPackageItem.selectedOptionValue;
  const validPackageItemIds = ProductsPage.freezeDriedPackageItemOptions().map(o => String(o.value));
  const selectedLocationId = selPkgFDLocation.selectedOptionValue;
  const validLocationIds = ProductsPage.productReadyLocationOptions().map(o => String(o.value));
  const selectedWeightG = rows.reduce((sum, r) => sum + Number(r.net_weight_g || 0), 0);
  const requiredWeightG = count * sizeG;
  return ProductsPage.canPackageFreezeDried() && Number.isFinite(count) && count > 0 && Number.isFinite(sizeG) && sizeG > 0 && selectedWeightG >= requiredWeightG && !!selectedPackageItemId && validPackageItemIds.includes(String(selectedPackageItemId)) && !!selectedLocationId && validLocationIds.includes(String(selectedLocationId));
}

