function () {
  const invalidNameParts = ["dark room", "fruiting", "freeze", "freezer", "fridge", "refrigerat", "cold shock", "lab", "shipped", "consumed", "compost", "expired", "retired"];
  const preferredNameParts = ["products storage", "product storage", "fulfillment", "shipping", "retail", "market", "customer"];
  return (qProductLocationOptions.data || []).filter(l => {
    const name = String(l.name || "").trim();
    const lower = name.toLowerCase();
    if (!name) return false;
    if (l.active === false) return false;
    if (invalidNameParts.some(part => lower.includes(part))) return false;
    return preferredNameParts.some(part => lower.includes(part));
  }).map(l => ({
    label: l.name,
    value: l.nocopk
  }));
}

