actionConfiguration.body:
async function () {
		if (!tblAgarFlasks.selectedRow || !tblAgarFlasks.selectedRow.nocopk) {
			showAlert("Select an agar flask lot first.", "warning");
			return;
		}

		const plateCount = Number(inpPlateCount.text);
		if (!Number.isFinite(plateCount) || plateCount <= 0) {
			showAlert("Enter a plate count greater than 0.", "warning");
			return;
		}

		if (!selAgarLocation.selectedOptionValue) {
			showAlert("Select a storage location for the poured plates.", "warning");
			return;
		}

		try {
			const res = await qPourPlates.run();
			const created = res?.[0]?.created_count ?? plateCount;

			showAlert(`Created ${created} plate lot(s).`, "success");

			inpPlateCount.setValue("");
			inpPourNotes.setValue("");
			resetWidget("dpPourOverride", true);

			await LabAgar.refresh();
			return res;
		} catch (e) {
			showAlert(e?.message || "Pour Plates failed.", "error");
			return null;
		}
	}

