function () {
  const row = tblFulfillmentOrders.selectedRow || ({});
  const method = String(row.payment_method || "");
  const status = String(row.clover_reconciliation_status || row.payment_state || "").toLowerCase();
  return !!row.airtable_record_id && method.startsWith("Sell on the Go") && status !== "reconciled" && status !== "accounted";
}

