actionConfiguration.body:
async function () {
  const row = tblFulfillmentOrders.selectedRow || ({});
  if (!row.airtable_record_id) {
    showAlert("Select an order first.", "warning");
    return null;
  }
  const res = await apiFulfillmentReconciliationAccounted.run();
  if (!res || res.ok === false) {
    showAlert(res && res.error || "Could not mark order accounted.", "error");
    return res;
  }
  await FulfillmentUI.refreshAfterReconciliation(res.message || "Order marked accounted.");
  return res;
}

