actionConfiguration.body:
async function () {
  const res = await apiFulfillmentAssignProduct.run();
  if (!res || res.ok === false) {
    showAlert(res && res.error || "Assignment failed", "error");
    return res;
  }
  const priorOrderId = appsmith.store.fulfillment_selected_order_id || "";
  showAlert(res && res.message || "Product assigned successfully", "success");
  const listRes = await apiFulfillmentListOrders.run();
  if (!listRes || listRes.ok === false) {
    showAlert(listRes && listRes.error || "Orders refresh failed", "error");
    return res;
  }
  const refreshedOrders = listRes.orders || [];
  const stillExists = !!priorOrderId && refreshedOrders.some(o => o.airtable_record_id === priorOrderId);
  if (!stillExists) {
    await FulfillmentUI.clearSelectionState();
    return res;
  }
  await storeValue("fulfillment_selected_order_id", priorOrderId);
  await FulfillmentUI.syncLinkedProductsFromSelectedOrder();
  const detailRes = await apiFulfillmentOrderDetail.run();
  if (detailRes && detailRes.ok !== false) {
    await storeValue("fulfillment_order_detail", detailRes);
  } else {
    await storeValue("fulfillment_order_detail", null);
  }
  const productRes = await apiFulfillmentProductSearch.run();
  if (productRes && productRes.ok !== false) {
    await storeValue("fulfillment_product_results", productRes.products || []);
  } else {
    await storeValue("fulfillment_product_results", []);
  }
  return res;
}

