function () {
  const rows = LotsSpawnToBulk.selectedLotRows();
  if (!rows.length) return "(No lots selected)";
  return rows.map(r => {
    const lotId = r.lot_id ?? r.nocopk;
    const inoc = r.inoculated_at ? moment(r.inoculated_at).format("YYYY-MM-DD") : "";
    const item = r.item_name_mat || r.item_name || "";
    const strain = r.strain_species_strain_mat || r.strain_species_strain || "";
    const status = r.status || "";
    return `${lotId} | inoc:${inoc} | ${item} | ${strain} | ${status}`.trim();
  }).join("\n");
}

