{{ ((options, serverSideFiltering) => ( 
  (() => {
    const rows = tblLots.selectedRows || [];
    if (!rows.length) return "";

    const locationIds = [...new Set(
      rows
        .map(r => r.location_id)
        .filter(v => v !== null && v !== undefined && v !== "")
        .map(v => String(v))
    )];

    if (locationIds.length !== 1) return "";

    const options = qFridgeFruitingLocations.data || [];
    const match = options.find(loc => String(loc.nocopk) === locationIds[0]);

    return match ? match.nocopk : "";
  })()
))(inpMoveLocation.options, inpMoveLocation.serverSideFiltering) }}

children.onOptionChange:
{{
  (() => {
    const label = String(inpMoveLocation.selectedOptionLabel || "");

    if (label.includes("Fruiting")) {
      radioMoveTransitionMode.setValue("Fruiting");
    } else if (label.includes("Fridge") || label.includes("Refrigerator")) {
      radioMoveTransitionMode.setValue("Fridge");
    } else {
      radioMoveTransitionMode.setValue("FullyColonized");
    }

    return true;
  })()
}}

