children.text:
{{
  (() => {
    const r = LotsDrawSyringes.selectedFlaskLot() || {};
    const mode = selDrawSyringeOutputType.selectedOptionValue || "product";
    const noun = mode === "product" ? "products" : "lots";
    const remaining = Number(r.remaining_volume_ml);
    const remainingText = Number.isFinite(remaining)
      ? " (" + remaining + " ml remaining)"
      : "";
    return "Create LC syringe " + noun + " from " + (r.lot_id || "the selected flask lot") + remainingText + ".";
  })()
}}

